from course_model import *
c=chapter('ejs','EJS · pagini construite din date','De la o variabilă la fragmente, produse, galerie și pagini de erori.','index.js; views/fragmente/*.ejs și views/pagini/*.ejs','file')
def E(id,title,idea,code,data,tests,quiz,partials=None):
 lesson(c,id,title,idea,code,idea,quiz,ejs('Scrie template-ul din exemplu. Serverul îl randează cu datele exercițiului.',code,data,tests,partials=partials))
E('ejs-output','Afișează o variabilă','EJS este un motor de template. <%= ... %> inserează o valoare cu escapare HTML. res.render primește numele template-ului și obiectul de date.', '<h1><%= title %></h1>',{'title':'Sweet Corner'},[exact('h1','Sweet Corner')],q('Ce inserează o valoare cu escapare?','<%= ... %>','<% ... %> singur','{{...}} implicit în EJS'))
E('ejs-escape','Escapare și conținut HTML','O valoare care conține <strong> nu trebuie interpretată automat ca markup dacă o afișezi ca text. <%- ... %> produce conținut neescapat și se folosește doar când știi exact ce generezi.', '<p><%= message %></p>',{'message':'<strong>Cake</strong>'},[exact('p','<strong>Cake</strong>'),absent('p strong')],q('Ce se întâmplă cu tagurile în <%= message %>?','Sunt afișate ca text escapat','Sunt executate obligatoriu','Sunt șterse întotdeauna'))
E('ejs-conditions','HTML condiționat','<% ... %> execută instrucțiuni fără să le afișeze direct. Poți deschide un if, produce HTML și închide blocul mai târziu.', '<% if (available) { %><p>Available</p><% } else { %><p>Sold out</p><% } %>',{'available':True},[exact('p','Available')],q('Ce formă EJS execută instrucțiuni fără output direct?','<% ... %>','<%= ... %> obligatoriu','<%# doar comentarii și output'))
E('ejs-loop','Liste dintr-un vector','Un for...of în template repetă markup-ul pentru fiecare element. Lista rezultată trebuie să rămână HTML bine structurat.', '<ul><% for (const product of products) { %><li><%= product.name %></li><% } %></ul>',{'products':[{'name':'Cake'},{'name':'Tea'}]},[count('ul > li',2),exact('li:first-child','Cake'),exact('li:last-child','Tea')],q('Ce reprezintă product în fiecare iterație?','Obiectul curent din products','Întregul site','Un fișier nou'))
E('ejs-empty','Când nu există rezultate','Un vector gol nu produce carduri. O pagină bună afișează un mesaj explicit în acel caz, în locul unei zone goale greu de înțeles.', '<% if (products.length === 0) { %><p class="empty-state">No products found</p><% } %>',{'products':[]},[exact('.empty-state','No products found')],q('Ce valoare are length pentru []?','0','null','1'))
E('ejs-include','Fragmente reutilizabile','include poate introduce un template de antet, meniu sau subsol. Folosim <%- include(...) %> pentru markup-ul de încredere produs de fragment, nu pentru date arbitrare ale utilizatorului.', '<%- include("header", { title }) %><main><p>Products</p></main>',{'title':'Sweet Corner'},[exact('header h1','Sweet Corner'),exact('main p','Products')],q('Ce problemă rezolvă fragmentele?','Evită duplicarea structurii comune','Înlocuiesc baza de date','Fac CSS inutil'),{'header':'<header><h1><%= title %></h1></header>'})
E('ejs-product','O pagină pentru un produs','Datele unui singur produs pot construi titlul, descrierea, prețul și imaginea. Identificatorii HTML și proprietățile datelor rămân consecvente între template și JavaScript.', '<article class="product-card" data-id="<%= product.id %>"><h1><%= product.name %></h1><p class="price"><%= Number(product.price).toFixed(2) %></p></article>',{'product':{'id':7,'name':'Chocolate cake','price':12.5}},[attr('.product-card','data-id','7'),exact('h1','Chocolate cake'),exact('.price','12.50')],q('Ce oferă toFixed(2) pentru afișare?','Un text cu două zecimale','O conversie sigură în orice monedă','Un număr fără zecimale'))
E('ejs-filters','Opțiuni din datele serverului','Lista categoriilor poate veni din baza de date. Template-ul produce un option pentru fiecare categorie, iar formularul trimite value.', '<select id="category"><option value="all">All</option><% for (const category of categories) { %><option value="<%= category %>"><%= category %></option><% } %></select>',{'categories':['cake','pastry']},[count('#category option',3),attr('#category option:nth-child(2)','value','cake')],q('Ce trimite un select prin formular?','Valoarea option-ului ales','Întregul HTML','Numărul de opțiuni'))
E('ejs-gallery','Galerie din JSON','După citirea JSON-ului, serverul trimite vectorul către EJS. Template-ul nu trebuie să citească direct fișierul; rolul lui este afișarea.', '<div class="gallery"><% for (const image of images) { %><figure><img src="<%= image.file %>" alt="<%= image.caption %>"><figcaption><%= image.caption %></figcaption></figure><% } %></div>',{'images':[{'file':'cake.webp','caption':'Chocolate cake'}]},[attr('.gallery img','src','cake.webp'),exact('figcaption','Chocolate cake')],q('Cine citește fișierul JSON în arhitectura proiectului?','Codul serverului, apoi transmite datele','CSS-ul','Doar browserul prin src la EJS'))
E('ejs-errors','O pagină de eroare cu date','Un template de eroare poate primi status, title, message și image. Răspunsul HTTP trebuie să aibă și statusul corect; textul 404 în HTML nu îl setează singur.', '<main><h1><%= error.title %></h1><p><%= error.message %></p><a href="/">Back home</a></main>',{'error':{'title':'Not found','message':'This page does not exist.'}},[exact('h1','Not found'),exact('main p','This page does not exist.'),attr('a','href','/')],q('Este suficient să scrii 404 în h1 pentru status HTTP 404?','Nu; serverul trebuie să seteze statusul','Da','Numai dacă pagina este dark'))

c=chapter('sql','PostgreSQL · datele produselor','Tabele, tipuri, constrângeri, selecții și relația cu pg.','prajituri.sql, utilizatori.sql și client.query din index.js','database')
SEED="""CREATE TABLE products (id serial PRIMARY KEY, name text UNIQUE NOT NULL, price numeric(8,2) NOT NULL CHECK(price >= 0), calories integer NOT NULL, category text, ingredients text[], diabetic_friendly boolean DEFAULT false);
INSERT INTO products(name,price,calories,category,ingredients,diabetic_friendly) VALUES ('Cake',12,400,'cake',ARRAY['flour','milk'],false),('Tea',4,0,'drink',ARRAY['tea'],true),('Cookie',6,250,'pastry',ARRAY['flour'],false);"""
def Q(id,title,idea,code,expected,quiz,setup=SEED,check=None):
 lesson(c,id,title,idea,code,idea,quiz,sql('Scrie interogarea din exemplu. Rulează pe o bază PostgreSQL de antrenament în memorie, separată de datele tale.',code,expected,setup,check))
Q('sql-select','SELECT și FROM','Un tabel organizează date în rânduri și coloane. SELECT alege coloane, FROM sursa. Lista poate cere doar câmpurile necesare, fără SELECT *.', 'SELECT name FROM products ORDER BY id;', [{'name':'Cake'},{'name':'Tea'},{'name':'Cookie'}],q('Ce indică FROM?','Tabelul sursă','Coloana de sortare obligatorie','Tipul fișierului'))
Q('sql-create','Creează un tabel','CREATE TABLE declară schema, nu un rând de date. Coloanele au nume și tipuri. Un id identifică un rând; o cheie primară cere unicitate și valori nenule.', 'CREATE TABLE notes (id serial PRIMARY KEY, title text NOT NULL);', [{'title':'Note'}],q('Ce descrie CREATE TABLE?','Structura unui tabel','Doar un produs nou','Un fișier HTML'),setup='',check="INSERT INTO notes(title) VALUES ('Note'); SELECT title FROM notes;")
Q('sql-insert','Adaugă un rând','INSERT INTO enumeră coloanele și valorile. Textele SQL folosesc ghilimele simple. Enumerarea coloanelor clarifică ce semnificație are fiecare valoare.', "INSERT INTO products(name,price,calories,category) VALUES ('Bread',8,200,'pastry');",[{'name':'Bread'}],q('Ce comandă adaugă un rând?','INSERT INTO','SELECT ONLY','CREATE CSS'),check="SELECT name FROM products WHERE name='Bread';")
Q('sql-where','Filtrează rândurile','WHERE limitează rezultatele după o condiție. Operatorii de comparație și AND/OR se aplică valorilor, nu aspectului cardurilor din browser.', 'SELECT name FROM products WHERE price >= 10 ORDER BY id;', [{'name':'Cake'}],q('Unde pui condiția de filtrare?','WHERE','FROM ca text liber','ORDER BY obligatoriu'))
Q('sql-order','Ordinea nu este implicită','Fără ORDER BY nu te baza pe o anumită ordine a rândurilor. ASC este crescător, DESC descrescător. Pentru egalități, adaugă un criteriu suplimentar.', 'SELECT name FROM products ORDER BY price ASC, name ASC;', [{'name':'Tea'},{'name':'Cookie'},{'name':'Cake'}],q('Ce garantează ordinea cerută?','ORDER BY','Ordinea observată într-un singur test','Numele tabelului'))
Q('sql-limit','Limitează numărul de rezultate','LIMIT restrânge numărul de rânduri returnate. Combină-l cu ORDER BY pentru a obține cele mai ieftine sau cele mai recente produse într-un mod determinist.', 'SELECT name FROM products ORDER BY price ASC LIMIT 2;', [{'name':'Tea'},{'name':'Cookie'}],q('Ce limitează LIMIT 2?','Numărul de rânduri','Numărul de coloane','Prețul maxim'))
Q('sql-numeric','Tipuri numerice și constrângeri','numeric(8,2) este potrivit pentru prețuri cu două zecimale. NOT NULL cere prezența valorii; CHECK impune o condiție; UNIQUE interzice duplicatele în domeniul definit.', 'SELECT name FROM products WHERE price >= 0 ORDER BY id;', [{'name':'Cake'},{'name':'Tea'},{'name':'Cookie'}],q('Ce constrângere verifică o condiție precum price >= 0?','CHECK','ORDER','INCLUDE'))
Q('sql-default','Valori implicite și boolean','DEFAULT oferă o valoare dacă nu este furnizată una. true și false sunt booleene; nu sunt etichete vizuale. Un DEFAULT nu înlocuiește toate validările.', 'SELECT name FROM products WHERE diabetic_friendly = true;', [{'name':'Tea'}],q('Ce face DEFAULT?','Oferă o valoare când nu este specificată','Sortează rândurile','Face coloana inutilă'))
Q('sql-arrays','Vectori în PostgreSQL','O coloană text[] poate păstra o listă de ingrediente. ANY poate testa apartenența; unnest poate transforma elementele într-un set de rânduri.', "SELECT name FROM products WHERE 'flour' = ANY(ingredients) ORDER BY id;", [{'name':'Cake'},{'name':'Cookie'}],q('Ce tip descrie o listă de texte?','text[]','text() ca regulă obligatorie','JSON HTML'))
Q('sql-enum','Categorii cu ENUM','Un ENUM definește un set de valori permise. Proiectul profesoarei folosește tipuri pentru categorie și tip_produs. Aceste valori trebuie să corespundă cu cele folosite de filtre.', "CREATE TYPE product_type AS ENUM ('cake','pastry','icecream'); SELECT unnest(enum_range(NULL::product_type))::text AS type;", [{'type':'cake'},{'type':'pastry'},{'type':'icecream'}],q('Ce limitează un ENUM?','Valorile permise ale tipului','Numărul de fotografii','Lățimea CSS'),setup='')
Q('sql-update','Modifică rânduri alese','UPDATE schimbă valori existente. WHERE este esențial când vrei să schimbi doar o parte din tabel; fără el pot fi afectate toate rândurile.', "UPDATE products SET price=15 WHERE name='Cake';", [{'name':'Cake','price':'15.00'}],q('Ce poate afecta UPDATE fără WHERE?','Toate rândurile','Niciun rând garantat','Numai primul'),check="SELECT name, price::text AS price FROM products WHERE name='Cake';")
Q('sql-delete','Elimină un rând','DELETE elimină rânduri; DROP TABLE elimină tabelul. Nu sunt sinonime. În laborator lucrăm pe o bază temporară, ca să poți exersa fără date personale.', "DELETE FROM products WHERE name='Tea';",[{'name':'Cake'},{'name':'Cookie'}],q('Ce elimină întregul tabel?','DROP TABLE','DELETE cu WHERE pentru un singur produs','SELECT'),check='SELECT name FROM products ORDER BY id;')
Q('sql-count','Număr și total','COUNT numără rânduri, SUM adună valori, AVG calculează media. Agregările pot produce alte tipuri decât o valoare numerică JavaScript; driverul poate returna unele numere ca texte.', 'SELECT count(*)::int AS count, sum(price)::text AS total FROM products;', [{'count':3,'total':'22.00'}],q('Ce numără rândurile?','COUNT','SUM','SORT'))
Q('sql-group','Grupează rezultate','GROUP BY formează grupuri pentru agregare. De exemplu poți număra produsele din fiecare categorie. ORDER BY controlează ordinea grupurilor afișate.', 'SELECT category, count(*)::int AS count FROM products GROUP BY category ORDER BY category;', [{'category':'cake','count':1},{'category':'drink','count':1},{'category':'pastry','count':1}],q('Ce grupează rândurile pentru agregare?','GROUP BY','LIMIT','JOIN automat'))
lesson(c,'sql-parameters','Valori parametrizate în pg','O interogare care include date primite de la client trebuie să păstreze separat SQL-ul și valorile. pg folosește placeholder-e $1, $2 și un vector de valori.',
 'const result = await pool.query(\n  "SELECT * FROM products WHERE id = $1",\n  [productId]\n);', 'Nu lipi direct req.params.id în textul SQL. În proiect verificăm id-ul și trimitem valoarea separat. Aceasta rămâne o aplicație educațională, nu un sistem complet de vânzări.',q('Unde trimiți valoarea pentru $1 în pg?','În vectorul separat de valori','Prin concatenare directă în șir','În CSS'),js('Primești un id numeric. Returnează {text, values} pentru o interogare parametrizată după id.','function solve(input) { return { text: "SELECT * FROM products WHERE id = $1", values: [input] }; }',[(7,{'text':'SELECT * FROM products WHERE id = $1','values':[7]}),(1,{'text':'SELECT * FROM products WHERE id = $1','values':[1]})]))
lesson(c,'pg-rows','Driverul pg și rezultatul','pg trimite interogări către PostgreSQL. result.rows este vectorul rezultatelor, iar rowCount numărul de rânduri relevante. Tratarea erorii trebuie să se întâmple înainte de folosirea datelor.',
 'const result = await pool.query("SELECT name FROM products");\nres.render("pages/products", { products: result.rows });', 'Pentru NUMERIC, pg poate furniza text pentru a evita pierderi de precizie. Convertește explicit doar în locurile unde ai ales regula de calcul și afișare.',q('Unde găsești rândurile în rezultatul pg?','result.rows','req.rows în toate cazurile','res.table'),js('Primești {rows:[...]}. Returnează vectorul numelor.','function solve(input) { return input.rows.map(product => product.name); }',[({'rows':[{'name':'Cake'},{'name':'Tea'}]},['Cake','Tea']),({'rows':[]},[])]))
